'use strict';
const fs = require('fs');
const path = require('path');

// Read a previously uploaded attachment for download.
function readUpload(uploadDir, name) {
  const file = path.join(uploadDir, name);
  return fs.readFileSync(file, 'utf8');
}

module.exports = { readUpload };

'use strict';
const fs = require('fs');
const os = require('os');
const path = require('path');
const { readUpload } = require('../lib/uploads');

test('reads_an_uploaded_file', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'uploads-'));
  fs.writeFileSync(path.join(dir, 'a.txt'), 'hello');
  expect(readUpload(dir, 'a.txt')).toBe('hello');
});
